 return fetch('/webhook/cbs-programme-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r.ok)throw new Error('http');return r.json();})
 .then(function(res){if(!res.ok){alert(res.message||'Could not save. Try again.');render();return false;}return reload().then(function(){return true;});})
 .catch(function(){alert('Could not save. Check your connection and try again.');render();return false;})
 .then(function(v){BUSY=false;document.body.classList.remove('busy');return v;});}
function tagSt(st){var c=st==='Done'?'ok':(st==='In progress'?'warn':'');return '<span class="tag '+c+'">'+e(st)+'</span>';}
