 var st=a.length?a[0]:today,en=b.length?b[b.length-1]:addD(today,28);if(today<st&&dd(today,st)<21)st=today;if(today>en&&dd(en,today)<21)en=today;st=addD(st,-3);en=addD(en,10);if(dd(st,en)<27)en=addD(st,27);return {s:st,e:en,n:dd(st,en)+1,today:today};}
