function wireGantt(){
 var R=range(),DW=ZOOM==='week'?12:30,gw=document.getElementById('gwrap');if(!gw)return;
 if(GSL!==null)gw.scrollLeft=GSL;else{var ti=dd(R.s,R.today);gw.scrollLeft=Math.max(0,ti*DW-160);}
