  b.addEventListener('pointerdown',function(ev){if(ev.button>0||BUSY)return;ev.preventDefault();
   var mode='move',tg=ev.target;if(!locked&&tg.classList.contains('hl'))mode='l';else if(!locked&&tg.classList.contains('hr'))mode='r';
   var x0=ev.clientX,st0=r.start_eff,en0=r.end_eff||r.start_eff;try{b.setPointerCapture(ev.pointerId);}catch(x){}b.classList.add('drag');
