   function calc(cx){var d=Math.round((cx-x0)/DW),a=st0,z=en0;if(mode==='move'){a=addD(st0,d);z=addD(en0,d);}else if(mode==='l'){a=addD(st0,d);if(a>z)a=z;}else{z=addD(en0,d);if(z<a)z=a;}return {d:d,s:a,e:z};}
   function mv(e2){var c=calc(e2.clientX);var l=dd(R.s,c.s)*DW+1,w=nd(c.s,c.e)*DW-2;b.style.left=l+'px';b.style.width=Math.max(w,8)+'px';tip.style.left=l+'px';tip.textContent=dmy(c.s)+' – '+dmy(c.e)+' ('+nd(c.s,c.e)+'d)';}
   function up(e2){b.removeEventListener('pointermove',mv);b.removeEventListener('pointerup',up);b.removeEventListener('pointercancel',up);tip.remove();b.classList.remove('drag');
    var c=calc(e2.clientX);
    if(e2.type==='pointercancel'){render();return;}
