    if(mode!=='move'){act({a:'set_dates',id:r.id,start_on:c.s,end_on:c.e,cascade:false});return;}
    var o=dlg('<h2>Move '+e(r.name)+'</h2><div class="m">From '+rng(st0,en0)+'</div><div class="m">To '+rng(c.s,c.e)+'</div>'+(locked?'<div class="note">Everything under this '+WORD[r.kind]+' moves with it.</div>':'')
     +'<div class="b" style="margin-top:14px"><button class="btn" id="mall">Move this and everything after</button><button class="btn ghost" id="mone">Move this only</button><button class="btn ghost" id="mx">Cancel</button></div>');
